// Общий модуль ЗакрытиеМесяцаСервер (Сервер = Истина, ВызовСервера = Ложь)

// Проверяет, есть ли в периоде непроведенные поступления по организации,
// независимо от того, видит ли их текущий пользователь.
//
Функция ЕстьНепроведенныеПоступления(Организация, НачалоПериода, КонецПериода) Экспорт

	УстановитьПривилегированныйРежим(Истина);

	Запрос = Новый Запрос;
	Запрос.Текст =
	"ВЫБРАТЬ ПЕРВЫЕ 1
	|	Поступление.Ссылка
	|ИЗ
	|	Документ.ПоступлениеТоваровУслуг КАК Поступление
	|ГДЕ
	|	Поступление.Организация = &Организация
	|	И Поступление.Дата МЕЖДУ &НачалоПериода И &КонецПериода
	|	И НЕ Поступление.Проведен
	|	И НЕ Поступление.ПометкаУдаления";
	Запрос.УстановитьПараметр("Организация", Организация);
	Запрос.УстановитьПараметр("НачалоПериода", НачалоДня(НачалоПериода));
	Запрос.УстановитьПараметр("КонецПериода", КонецДня(КонецПериода));

	Возврат Не Запрос.Выполнить().Пустой();

