Процедура ПересчитатьСуммыВВалютуУчета(Документы, ДатаПересчета) Экспорт

	НачатьТранзакцию();
	Попытка

		Блокировка = Новый БлокировкаДанных;
		ЭлементБлокировки = Блокировка.Добавить("РегистрСведений.КурсыВалют");
		ЭлементБлокировки.Режим = РежимБлокировкиДанных.Разделяемый;
		Для Каждого ДокументСсылка Из Документы Цикл
			ЭлементБлокировки = Блокировка.Добавить(ДокументСсылка.Метаданные().ПолноеИмя());
			ЭлементБлокировки.УстановитьЗначение("Ссылка", ДокументСсылка);
		КонецЦикла;
		Блокировка.Заблокировать();

		Курсы = КурсыВалютНаДату(ДатаПересчета);

		Для Каждого ДокументСсылка Из Документы Цикл
			ДокументОбъект = ДокументСсылка.ПолучитьОбъект();
			Курс = Курсы.Получить(ДокументОбъект.ВалютаДокумента);
			Если Курс = Неопределено Тогда
				ВызватьИсключение СтрШаблон(НСтр("ru = 'Нет курса %1 на %2'"),
					ДокументОбъект.ВалютаДокумента, Формат(ДатаПересчета, "ДЛФ=D"));
			КонецЕсли;
			ДокументОбъект.СуммаУпр = Окр(ДокументОбъект.СуммаДокумента * Курс, 2);
			ДокументОбъект.Записать(РежимЗаписиДокумента.Запись);
		КонецЦикла;

		ЗафиксироватьТранзакцию();
	Исключение
		ОтменитьТранзакцию();
		ВызватьИсключение;
	КонецПопытки;

КонецПроцедуры

Процедура ОбработкаПроведения(Отказ, РежимПроведения)

	Блокировка = Новый БлокировкаДанных;
	ЭлементБлокировки = Блокировка.Добавить("РегистрНакопления.ТоварыВРезерве");
	ЭлементБлокировки.Режим = РежимБлокировкиДанных.Исключительный;
	ЭлементБлокировки = Блокировка.Добавить("РегистрНакопления.ТоварыНаСкладах");
	ЭлементБлокировки.Режим = РежимБлокировкиДанных.Исключительный;
	Блокировка.Заблокировать();

	Запрос = Новый Запрос;
	Запрос.Текст =
	"ВЫБРАТЬ
	|	Товары.Номенклатура КАК Номенклатура,
	|	СУММА(Товары.Количество) КАК Количество
	|ИЗ
	|	Документ.ЗаказНаПеремещение.Товары КАК Товары
	|ГДЕ
	|	Товары.Ссылка = &Ссылка
	|
	|СГРУППИРОВАТЬ ПО
	|	Товары.Номенклатура";
	Запрос.УстановитьПараметр("Ссылка", Ссылка);
	Выборка = Запрос.Выполнить().Выбрать();

	Движения.ТоварыВРезерве.Записывать = Истина;
	Пока Выборка.Следующий() Цикл
		Движение = Движения.ТоварыВРезерве.ДобавитьПриход();
		Движение.Период = Дата;
		Движение.Склад = СкладОтправитель;
		Движение.Номенклатура = Выборка.Номенклатура;
		Движение.ЗаказНаПеремещение = Ссылка;
		Движение.Количество = Выборка.Количество;
	КонецЦикла;

КонецПроцедуры

